const x = data.series[0].fields.find(f => f.name === 'TMDB Score').values;
const y = data.series[0].fields.find(f => f.name === 'Reddit Buzz Score').values;
const text = data.series[0].fields.find(f => f.name === 'Movie').values;

return {
  data: [{
    x: x,
    y: y,
    text: text,
    type: 'scatter',
    mode: 'markers',
    marker: {
      size: 10,
      color: '#1f77b4',
      opacity: 0.7
    },
    hovertemplate: '<b>%{text}</b><br>TMDB: %{x:.1f}<br>Reddit: %{y:.1f}<extra></extra>'
  }],
  layout: {
    xaxis: { title: 'TMDB Score', range: [0, 100] },
    yaxis: { title: 'Reddit Buzz Score', range: [0, 100] },
    hovermode: 'closest',
    showlegend: false
  }
};
